// Freie Slots aus Google Calendar berechnen
const calendarData = $input.first().json;
const prevData = $node['🔍 Antwort parsen'].json;

const busySlots = calendarData.calendars?.[$env.GOOGLE_CALENDAR_ID]?.busy || [];

// Verfügbare 30-min-Slots Mo-Fr 9-17 Uhr in den nächsten 5 Tagen
const availableSlots = [];
const now = new Date();
const days = ['Sonntag','Montag','Dienstag','Mittwoch','Donnerstag','Freitag','Samstag'];

for (let d = 1; d <= 7 && availableSlots.length < 6; d++) {
  const date = new Date(now);
  date.setDate(now.getDate() + d);
  if (date.getDay() === 0 || date.getDay() === 6) continue; // Skip weekends

  for (const hour of [9, 10, 11, 14, 15, 16]) {
    if (availableSlots.length >= 6) break;
    const slotStart = new Date(date);
    slotStart.setHours(hour, 0, 0, 0);
    const slotEnd = new Date(slotStart);
    slotEnd.setMinutes(30);

    // Prüfen ob Slot frei ist
    const isBusy = busySlots.some(busy => {
      const bs = new Date(busy.start);
      const be = new Date(busy.end);
      return slotStart < be && slotEnd > bs;
    });

    if (!isBusy && slotStart > now) {
      const dateStr = slotStart.toLocaleDateString('de-DE', {
        weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
      });
      const timeStr = slotStart.toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit' });
      availableSlots.push({
        id: slotStart.toISOString(),
        label: `${dateStr} um ${timeStr} Uhr`,
        datetime: slotStart.toISOString()
      });
    }
  }
}

const slotsText = availableSlots.length > 0
  ? availableSlots.map((s, i) => `${i + 1}. ${s.label}`).join('\n')
  : 'Leider sind in den nächsten 7 Tagen keine Termine verfügbar. Unser Team kontaktiert Sie direkt.';

const responseMessage = `Super! Gerne vereinbare ich einen Termin für Sie. Hier sind unsere verfügbaren Termine:\n\n${slotsText}\n\nBitte antworten Sie mit der Nummer Ihres Wunsch-Termins.`;

return [{ json: {
  ...prevData,
  response_text: responseMessage,
  available_slots: availableSlots,
  action: 'select_slot'
}}];

// Normaler Gesprächsverlauf – Antwort direkt zurückgeben
const data = $node['🔍 Antwort parsen'].json;
return [{ json: {
  response_text: data.response_text || '',
  action: data.action || 'continue_conversation',
  session_id: data.session_id,
  channel: data.channel,
  user_identifier: data.user_identifier
}}];
